/// <summary>
/// Intrinsic function parameter validator
/// </summary>
internal final class MXTXppIntrinsicFunctionHelper
{
}

Method.Source:
private static void throwArgumentException(str _argValue, str _expectedType)
{
    throw new System.Exception(strFmt("'%1' argument does not specify a known %2.", _argValue, _expectedType));
}

	public static void validateClassName(str _className)
    {
        if (className2Id(_className) == 0)
        {
            MXTXppIntrinsicFunctionHelper::throwArgumentException(_className, 'class');
        }
	}

public static void validateFormName(str _formName)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetForm(_formName) == null)
    {
        throw new System.Exception(strFmt("Form '%1' is not found.", _formName));
    }
}

public static void validateTableName(str _tableName)
{
    if (tableName2Id(_tableName) == 0)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_tableName, 'table/map/view/data entity');
    }
}

public static void validateFieldName(str _tableName, str _fieldName)
{
    MXTXppIntrinsicFunctionHelper::validateTableName(_tableName);

    if (fieldName2Id(tableName2Id(_tableName), _fieldName) == 0)
    {
        throw new System.Exception(strFmt("Table '%1' does not contain a field named '%2'.", _tableName, _fieldName));
    }
}

public static void validateEDTName(str _edtName)
{
    if (extendedTypeName2Id(_edtName) == 0)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_edtName, 'extended data type');
    }
}

public static void validateMenuItem(str _menuItemName, MenuItemType _type)
{
    switch (_type)
    {
        case MenuItemType::Action:
            if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetMenuItemAction(_menuItemName) == null)
            {
                MXTXppIntrinsicFunctionHelper::throwArgumentException(_menuItemName, 'menu item action');
            }
            break;

        case MenuItemType::Display:
            if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetMenuItemDisplay(_menuItemName) == null)
            {
                MXTXppIntrinsicFunctionHelper::throwArgumentException(_menuItemName, 'menu item display');
            }
            break;

        case MenuItemType::Output:
            if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetMenuItemOutput(_menuItemName) == null)
            {
                MXTXppIntrinsicFunctionHelper::throwArgumentException(_menuItemName, 'menu item output');
            }
            break;
    }
}

public static void validateInstanceMethod(str _className, str _methodName)
{
    MXTXppIntrinsicFunctionHelper::validateClassName(_className);

    SysDictClass dictClass = new SysDictClass(className2Id(_className));

    if (!dictClass.hasObjectMethod(_methodName))
    {
        throw new System.Exception(strFmt("The instance method designated by argument '%1' dos not exist.", _methodName));
    }
}

public static void validateStaticMethod(str _className, str _methodName)
{
    MXTXppIntrinsicFunctionHelper::validateClassName(_className);

    SysDictClass dictClass = new SysDictClass(className2Id(_className));

    if (!dictClass.hasStaticMethod(_methodName))
    {
        throw new System.Exception(strFmt("The static method designated by argument '%1' dos not exist.", _methodName));
    }
}

public static void validateEnumName(str _enumName)
{
    if (enumName2Id(_enumName) == 0)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_enumName, 'enumeration');
    }
}

public static void validateEnumValue(str _enumName, str _enumValue)
{
    MXTXppIntrinsicFunctionHelper::validateEnumName(_enumName);

    var sysDictEnum = new SysDictEnum(enumName2Id(_enumName));
    for(int i = 0 ; i <= sysDictEnum.values() ; i++)
    {
        if(sysDictEnum.index2Name(i) == _enumValue)
        {
            return;
        }
    }

    throw new System.Exception(strFmt("Enumerable '%1' does not contain a value named '%2'.", _enumName, _enumValue));
}

public static void validateAttributeName(str _attributeName)
{
    if (className2Id(_attributeName) == 0)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_attributeName, 'attribute');
    }

    DictClass dictClass = SysDictClass::newName(_attributeName);

    if (dictClass.extend() != classNum(SysAttribute))
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_attributeName, 'attribute');
    }
}

public static void validateConfigurationKeyName(str _configurationKeyName)
{
    if (configurationKeyName2Id(_configurationKeyName) == 0)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_configurationKeyName, 'configuration key');
    }
}

public static void validateDataEntityName(str _dataEntityName)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetDataEntity(_dataEntityName) == null)
    {
        throw new System.Exception(strFmt("Data entity '%1' is not found.", _dataEntityName));
    }
}

public static void validateRoleName(str _roleName)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetSecurityRole(_roleName) == null)
    {
        throw new System.Exception(strFmt("Security role '%1' is not found.", _roleName));
    }
}

public static void validateDataEntityViewName(str _name)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetDataEntityView(_name) == null &&
        Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetDataEntity(_name) == null)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_name, 'data entity');
    }
}

public static void validateViewName(str _name)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetView(_name) == null)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_name, 'view');
    }
}

public static void validateMapName(str _name)
{
    if (Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetMap(_name) == null)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_name, 'map');
    }
}

public static void validateServiceName(str _name)
{
    System.Collections.Specialized.StringEnumerator names =
        Microsoft.Dynamics.Ax.Xpp.MetadataSupport::ServiceNames();

    while (names.MoveNext())
    {
        if (names.Current == _name)
        {
            return;
        }
    }

    MXTXppIntrinsicFunctionHelper::throwArgumentException(_name, 'service');
}

public static void validateDataEntityDataSource(str _entityName, str _dataSourceName)
{
    var entity = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetDataEntityView(_entityName);

    if (entity == null)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_entityName, 'data entity');
    }

    if (entity.ViewMetadata == null || !entity.ViewMetadata.DataSources.Contains(_dataSourceName))
    {
        throw new System.Exception(strFmt("Data entity '%1' does not contain a data source named '%2'.", _entityName, _dataSourceName));
    }
}

public static void validateIndexName(str _tableName, str _indexName)
{
    MXTXppIntrinsicFunctionHelper::validateTableName(_tableName);

    if (!indexName2Id(tableName2Id(_tableName), _indexName))
    {
        throw new System.Exception(strFmt("Table '%1' does not contain an index named '%2'.", _tableName, _indexName));
    }
}

public static void validateTableMethod(str _tableName, str _methodName, boolean _mustBeStatic)
{
    MXTXppIntrinsicFunctionHelper::validateTableName(_tableName);
    SysDictTable dictTable = SysDictTable::newName(_tableName);
    Set methods = dictTable.methods(true, true, true, tableStr(Common));
    SetEnumerator enumerator = methods.getEnumerator();

    while (enumerator.moveNext())
    {
        SysDictMethod method = enumerator.current() as SysDictMethod;
        if (method.name() == _methodName && method.isStatic() == _mustBeStatic)
        {
            return;
        }
    }

    throw new System.Exception(strFmt("Table '%1' does not contain the %2 method '%3'.",
        _tableName, _mustBeStatic ? 'static' : 'instance', _methodName));
}

public static void validateFormDataSource(str _formName, str _dataSourceName)
{
    var form = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetForm(_formName);
    if (form == null)
    {
        MXTXppIntrinsicFunctionHelper::throwArgumentException(_formName, 'form');
    }
    if (!form.DataSources.Contains(_dataSourceName))
    {
        throw new System.Exception(strFmt("Form '%1' does not contain a data source named '%2'.", _formName, _dataSourceName));
    }
}

public static void validateFormDataField(str _formName, str _dataSourceName, str _fieldName)
{
    MXTXppIntrinsicFunctionHelper::validateFormDataSource(_formName, _dataSourceName);
    var form = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetForm(_formName);
    var dataSource = form.DataSources.getObject(_dataSourceName);
    if (!dataSource.Fields.Contains(_fieldName))
    {
        throw new System.Exception(strFmt("Form data source '%1.%2' does not contain a field named '%3'.",
            _formName, _dataSourceName, _fieldName));
    }
}

public static void validateFormMethod(str _formName, str _methodName)
{
    var form = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetForm(_formName);
    if (form == null || !form.Methods.Contains(_methodName))
    {
        throw new System.Exception(strFmt("Form '%1' does not contain a method named '%2'.", _formName, _methodName));
    }
}

public static void validateFormControl(str _formName, str _controlName)
{
    var form = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetForm(_formName);
    if (form == null || !MXTXppIntrinsicFunctionHelper::containsNamedChild(form.Design, 'Controls', _controlName))
    {
        throw new System.Exception(strFmt("Form '%1' does not contain a control named '%2'.", _formName, _controlName));
    }
}

private static boolean containsNamedChild(System.Object _parent, str _collectionProperty, str _name)
{
    if (_parent == null) return false;

    System.Reflection.PropertyInfo collectionProperty = _parent.GetType().GetProperty(_collectionProperty);
    if (collectionProperty == null) return false;

    System.Collections.IEnumerable children = collectionProperty.GetValue(_parent) as System.Collections.IEnumerable;
    if (children == null) return false;

    System.Collections.IEnumerator childEnumerator = children.GetEnumerator();
    while (childEnumerator.MoveNext())
    {
        System.Object child = childEnumerator.Current;
        System.Reflection.PropertyInfo nameProperty = child.GetType().GetProperty('Name');
        if (nameProperty != null && nameProperty.GetValue(child) == _name)
        {
            return true;
        }

        if (MXTXppIntrinsicFunctionHelper::containsNamedChild(child, _collectionProperty, _name))
        {
            return true;
        }
    }

    return false;
}

public static void validateTableFieldGroup(str _tableName, str _fieldGroupName)
{
    var table = Microsoft.Dynamics.Ax.Xpp.MetadataSupport::GetTable(_tableName);
    if (table == null || !table.FieldGroups.Contains(_fieldGroupName))
    {
        throw new System.Exception(strFmt("Table '%1' does not contain a field group named '%2'.", _tableName, _fieldGroupName));
    }
}
